  SELECT id INTO m_118_h_r_4366 FROM vr_measures
   WHERE congress = 118 AND chamber = 'house' AND number = 'H.R. 4366' LIMIT 1;
  IF m_118_h_r_4366 IS NULL THEN
    INSERT INTO vr_measures (measure_type, congress, chamber, number, title, short_title, summary, introduced_at, status, source_url, source_label, external_ids)
    VALUES ('bill', 118, 'house', 'H.R. 4366', 'Consolidated Appropriations Act, 2024', 'Consolidated Appropriations Act, 2024',
      'The first of the two fiscal-year-2024 appropriations packages, enacted 2024-03-09 as P.L. 118-42. Division A is the Military Construction, Veterans Affairs, and Related Agencies Appropriations Act, 2024, whose Section 413 (138 Stat. 65) carries the enacted text of S.Amdt. 1354. Created here only as the parent vehicle for that amendment; it carries NO firearms issue mapping, because a vote on a multi-division appropriations act is not a firearms position.',
      DATE '2023-06-29', 'enacted', 'https://www.govinfo.gov/content/pkg/PLAW-118publ42/html/PLAW-118publ42.htm', 'GovInfo — P.L. 118-42', '{"congressGovId":"hr4366-118","publicLaw":"118-42","billStatus":"https://www.govinfo.gov/bulkdata/BILLSTATUS/118/hr/BILLSTATUS-118hr4366.xml"}'::jsonb)
    RETURNING id INTO m_118_h_r_4366;
  END IF;

  -- S.Amdt. 1354 (118th senate) — Kennedy amendment prohibiting VA reporting of fiduciary determinations to NICS
  SELECT id INTO m_118_s_amdt_1354 FROM vr_measures
   WHERE congress = 118 AND chamber = 'senate' AND number = 'S.Amdt. 1354' LIMIT 1;
  IF m_118_s_amdt_1354 IS NULL THEN
    INSERT INTO vr_measures (measure_type, congress, chamber, number, title, short_title, summary, introduced_at, status, source_url, source_label, external_ids, parent_id)
    VALUES ('amendment', 118, 'senate', 'S.Amdt. 1354', 'Kennedy amendment prohibiting VA reporting of fiduciary determinations to NICS', 'Kennedy VA/NICS Amendment (S.Amdt. 1354)',
      'Second-degree amendment to the Military Construction, Veterans Affairs, and Related Agencies appropriations division of H.R. 4366, offered by Senator John Kennedy: "To prohibit the availability of funds for the Secretary of Veterans Affairs to report certain information to the Department of Justice for use by the National Instant Criminal Background Check System." Agreed to 53-45 on 2023-10-25 with eleven Democrats voting yea. Enacted as Section 413 of Division A of the Consolidated Appropriations Act, 2024 (P.L. 118-42, 138 Stat. 65), which bars the use of Division A funds to report to the Attorney General, for NICS purposes, that a person deemed mentally incapacitated, mentally incompetent or experiencing an extended loss of consciousness has been adjudicated a mental defective under 18 U.S.C. 922(d)(4) and (g)(4), unless a judicial authority has found that the person is a danger to themselves or others.',
      DATE '2023-10-25', 'enacted', 'https://www.govinfo.gov/content/pkg/PLAW-118publ42/html/PLAW-118publ42.htm', 'GovInfo — P.L. 118-42', '{"senateVote":"118-1-268","publicLaw":"118-42"}'::jsonb, m_118_h_r_4366)
    RETURNING id INTO m_118_s_amdt_1354;
  ELSE
    UPDATE vr_measures SET parent_id = m_118_h_r_4366, updated_at = now()
     WHERE id = m_118_s_amdt_1354 AND parent_id IS NULL;
  END IF;

  -- H.R. 1041 (119th house) — Veterans 2nd Amendment Protection Act
  SELECT id INTO m_119_h_r_1041 FROM vr_measures
   WHERE congress = 119 AND chamber = 'house' AND number = 'H.R. 1041' LIMIT 1;
  IF m_119_h_r_1041 IS NULL THEN
    INSERT INTO vr_measures (measure_type, congress, chamber, number, title, short_title, summary, introduced_at, status, source_url, source_label, external_ids)
    VALUES ('bill', 119, 'house', 'H.R. 1041', 'Veterans 2nd Amendment Protection Act', 'Veterans 2nd Amendment Protection Act',
      'Adds a new 38 U.S.C. 5501B barring the Department of Veterans Affairs from transmitting a beneficiary''s personally identifiable information to the Department of Justice for inclusion in the National Instant Criminal Background Check System on the basis of a determination under 38 U.S.C. 5502 that the beneficiary is unable to manage their own benefit payments and requires a fiduciary, unless a judge, magistrate or other judicial authority has found that the beneficiary is a danger to themselves or others. Passed the House 216-201 on 2026-05-21; the Senate has not taken it up. Codifies as permanent law the same policy that Section 413 of Division A of P.L. 118-42 imposed for one fiscal year as an appropriations restriction.',
      DATE '2025-02-05', 'passed_house', 'https://www.congress.gov/bill/119th-congress/house-bill/1041', 'Congress.gov', '{"congressGovId":"hr1041-119","billStatus":"https://www.govinfo.gov/bulkdata/BILLSTATUS/119/hr/BILLSTATUS-119hr1041.xml"}'::jsonb)
    RETURNING id INTO m_119_h_r_1041;
  END IF;

